57	export function* handleJSEntityRedirect(deletedId: string) {
58	  const pageId: string = yield select(getCurrentPageId);
59	  const allJsItems: EntityItem[] = yield select(getJSSegmentItems);
60	  const redirectAction = getNextEntityAfterDelete(deletedId, allJsItems);
61	  switch (redirectAction.action) {
62	    case RedirectAction.CREATE:
63	      history.push(jsCollectionAddURL({ pageId }));
64	      break;
65	    case RedirectAction.ITEM:
66	      if (!redirectAction.payload) {
67	        log.error("Redirect item does not have a payload");
68	        history.push(jsCollectionAddURL({ pageId }));
69	        break;
70	      }
71	      const { payload } = redirectAction;
72	      history.push(getJSEntityItemUrl(payload, pageId));
73	      break;
74	  }
75	}
76	
77	export function* handleQueryEntityRedirect(deletedId: string) {
78	  const pageId: string = yield select(getCurrentPageId);
79	  const allQueryItems: EntityItem[] = yield select(getQuerySegmentItems);
80	  const redirectAction = getNextEntityAfterDelete(deletedId, allQueryItems);
81	  switch (redirectAction.action) {
82	    case RedirectAction.CREATE:
83	      history.push(queryAddURL({ pageId }));
84	      break;
85	    case RedirectAction.ITEM:
86	      if (!redirectAction.payload) {
87	        history.push(queryAddURL({ pageId }));
88	        log.error("Redirect item does not have a payload");
89	        break;
90	      }
91	      const { payload } = redirectAction;
92	      history.push(getQueryEntityItemUrl(payload, pageId));
93	      break;
94	  }
95	}
