1	interface Connection {
2	  onMessage: (type: string, fn: (data: unknown) => void) => () => void;
3	  postMessage: (message: unknown) => void;
4	  window: Window | null;
5	}
6	
7	const createChannel = (): Connection => {
8	  const builderWindow = window.open(
9	    `${window.location.pathname}/builder`,
10	    "_blank",
11	  );
12	
13	  const onMessageMap = new Map<string, ((data: unknown) => void)[]>();
14	
15	  function onMessage(type: string, fn: (data: unknown) => void) {
16	    let eventHandlerList = onMessageMap.get(type);
17	
18	    if (eventHandlerList && eventHandlerList instanceof Array) {
19	      eventHandlerList.push(fn);
20	    } else {
21	      eventHandlerList = [fn];
22	      onMessageMap.set(type, eventHandlerList);
23	    }
24	    return () => {
25	      if (eventHandlerList) {
26	        const index = eventHandlerList.indexOf(fn);
27	
28	        if (index > -1) {
29	          eventHandlerList.splice(index, 1);
30	        }
31	      }
32	    };
33	  }
34	
35	  window?.addEventListener("message", (event) => {
36	    if (event.source === builderWindow) {
37	      const handlerList = onMessageMap.get(event.data.type);
38	      if (handlerList) {
39	        handlerList.forEach((fn) => fn(event.data));
40	      }
41	    }
42	  });
43	
44	  const postMessage = (message: unknown) => {
45	    builderWindow?.postMessage(message, "*");
46	  };
47	
48	  return {
49	    window: builderWindow,
50	    postMessage,
51	    onMessage,
52	  };
53	};
54	
55	export default class CustomWidgetBuilderService {
56	  private static builderWindowConnections: Map<string, Connection> = new Map();
57	
58	  static createConnection(widgetId: string) {
59	    const channel = createChannel();
60	    this.builderWindowConnections.set(widgetId, channel);
61	    return channel;
62	  }
63	
64	  static isConnected(widgetId: string) {
65	    const connection = this.builderWindowConnections.get(widgetId);
66	
67	    return connection && connection.window && !connection.window.closed;
68	  }
69	
70	  static focus(widgetId: string) {
71	    if (this.isConnected(widgetId)) {
72	      this.builderWindowConnections.get(widgetId)?.window?.focus();
73	    }
74	  }
75	
76	  static getConnection(widgetId: string) {
77	    if (this.isConnected(widgetId)) {
78	      const { onMessage, postMessage } = this.builderWindowConnections.get(
79	        widgetId,
80	      ) as Connection;
81	
82	      return {
83	        onMessage,
84	        postMessage,
85	      };
86	    }
87	  }
88	
89	  static closeConnection(widgetId: string, skipClosing?: boolean) {
90	    if (this.builderWindowConnections.has(widgetId)) {
91	      if (!skipClosing) {
92	        const connection = this.builderWindowConnections.get(widgetId);
93	
94	        connection?.window?.close();
95	      }
96	
97	      this.builderWindowConnections.delete(widgetId);
98	    }
99	  }
100	
101	  static closeAllConnections() {
102	    this.builderWindowConnections.forEach((connection) => {
103	      connection?.window?.close();
104	    });
105	
106	    this.builderWindowConnections.clear();
107	  }
108	}
