export class Builder {
  // The window that hosts the custom widget builder popup
  builderWindow: Window | null;

  // Registered message listeners keyed by message type
  onMessageMap: Map<string, MessageCallback[]> = new Map();

  constructor() {
    this.builderWindow = window.open(
      `${window.location.pathname}/builder`,
      "_blank",
    );

    window.addEventListener("message", this.handleMessage);
  }

  private handleMessage = (event: MessageEvent) => {
    if (event.source === this.builderWindow) {
      const handlerList = this.onMessageMap.get(event.data.type);

      if (handlerList) {
        handlerList.forEach((fn) => fn(event.data));
      }
    }
  };

  onMessage = (type: string, callback: MessageCallback) => {
    let eventHandlerList = this.onMessageMap.get(type);

    if (eventHandlerList && eventHandlerList instanceof Array) {
      eventHandlerList.push(callback);
    } else {
      eventHandlerList = [callback];
      this.onMessageMap.set(type, eventHandlerList);
    }

    return () => {
      if (eventHandlerList) {
        const index = eventHandlerList.indexOf(callback);

        if (index > -1) {
          eventHandlerList.splice(index, 1);
        }
      }
    };
  };

  postMessage = (message: unknown) => {
    this.builderWindow?.postMessage(message, "*");
  };

  isConnected = () => {
    return !!this.builderWindow && !this.builderWindow.closed;
  };

  focus = () => {
    if (this.isConnected()) {
      this.builderWindow?.focus();
    }
  };

  close = (closeWindow?: boolean) => {
    window.removeEventListener("message", this.handleMessage);

    if (closeWindow) {
      this.builderWindow?.close();
    }
  };
}

export type BuilderFactory = () => Builder;

export default class CustomWidgetBuilderService {
  private static builders: Map<string, Builder> = new Map();

  private static builderFactory: BuilderFactory = () => new Builder();

  static setBuilderFactory(factory: BuilderFactory) {
    this.builderFactory = factory;
  }

  static createBuilder(widgetId: string) {
    const builder = this.builderFactory();

    this.builders.set(widgetId, builder);

    return builder;
  }

  static isConnected(widgetId: string) {
    const builder = this.builders.get(widgetId);

    return !!builder && builder.isConnected();
  }

  static focus(widgetId: string) {
    if (this.isConnected(widgetId)) {
      this.builders.get(widgetId)?.focus();
    }
  }

  static closeBuilder(widgetId: string, closeWindow?: boolean) {
    const builder = this.builders.get(widgetId);

    if (builder) {
      builder.close(closeWindow);

      this.builders.delete(widgetId);
    }
  }

  static getBuilder(widgetId: string) {
    return this.builders.get(widgetId);
  }
}
